package com.gdad.bags.data.vendorfinance
import com.gdad.bags.data.local.CacheOwner
import com.gdad.bags.data.remote.*
import com.gdad.bags.domain.model.*
import com.gdad.bags.domain.product.*
import com.gdad.bags.domain.purchase.*
import com.gdad.bags.domain.vendorfinance.*
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Test
class ProductionVendorFinanceRepositoryTest{
 @Test fun salesmanCannotReadOrMutate()=runBlocking{val remote=Remote();val repo=ProductionVendorFinanceRepository(remote,Purchases(),Products());val user=OWNER.copy(role=UserRole.SALESMAN);assertTrue(repo.load(user)is VendorFinanceResult.Failure);assertTrue(repo.postPayment(user,REQUEST,PAYMENT)is VendorFinanceResult.Failure);assertEquals(0,remote.loads)}
 @Test fun ownerLoadsAndPaymentRefreshesDue()=runBlocking{val remote=Remote();val purchases=Purchases();val repo=ProductionVendorFinanceRepository(remote,purchases,Products());assertEquals(BILL,(repo.load(OWNER)as VendorFinanceResult.Success).value.bills.single());assertEquals(POSTED_PAYMENT,(repo.postPayment(OWNER,REQUEST,PAYMENT)as VendorFinanceResult.Success).value);assertEquals(1,purchases.refreshes)}
 @Test fun returnRefreshesStockAndInvalidInputNeverCallsRemote()=runBlocking{val remote=Remote();val products=Products();val repo=ProductionVendorFinanceRepository(remote,Purchases(),products);assertTrue(repo.postReturn(OWNER,REQUEST,RETURN.copy(reason=""))is VendorFinanceResult.Failure);assertEquals(0,remote.returns);assertEquals(POSTED_RETURN,(repo.postReturn(OWNER,REQUEST,RETURN)as VendorFinanceResult.Success).value);assertEquals(1,products.refreshes)}
 @Test fun combinedPaymentOverflowNeverReachesRemote()=runBlocking{val remote=Remote();val repo=ProductionVendorFinanceRepository(remote,Purchases(),Products());val overflow=PAYMENT.copy(allocations=listOf(VendorPaymentAllocationDraft(BILL_ID,Long.MAX_VALUE),VendorPaymentAllocationDraft("88888888-8888-4888-8888-888888888888",1)));assertTrue(repo.postPayment(OWNER,REQUEST,overflow)is VendorFinanceResult.Failure);assertEquals(0,remote.payments)}
 private class Remote:VendorFinanceRemoteDataSource{var loads=0;var returns=0;var payments=0;override suspend fun load(owner:CacheOwner):RemoteResult<VendorLedger>{loads++;return RemoteResult.Success(LEDGER)};override suspend fun postPayment(owner:CacheOwner,requestId:String,draft:VendorPaymentDraft):RemoteResult<PostedVendorPayment>{payments++;return RemoteResult.Success(POSTED_PAYMENT)};override suspend fun postReturn(owner:CacheOwner,requestId:String,draft:VendorReturnDraft):RemoteResult<PostedVendorReturn>{returns++;return RemoteResult.Success(POSTED_RETURN)};override suspend fun reverse(owner:CacheOwner,requestId:String,draft:VendorReversalDraft)=RemoteResult.Success(PostedVendorReversal("payment",EVENT,null))}
 private class Purchases:PurchaseManagementRepository{var refreshes=0;override fun observe(session:UserSession):Flow<PurchaseDirectory> = flowOf(PurchaseDirectory());override suspend fun refresh(session:UserSession):PurchaseResult<Unit>{refreshes++;return PurchaseResult.Success(Unit,"ok")};override suspend fun manageVendor(session:UserSession,requestId:String,mutation:VendorMutation,draft:VendorDraft)=PurchaseResult.Success(Unit,"ok");override suspend fun postPurchase(session:UserSession,requestId:String,draft:PurchaseDraft)=PurchaseResult.Success(PostedPurchase(BILL_ID,"99999999-9999-4999-8999-999999999999",null,10000,0,10000,1),"ok")}
 private class Products:ProductCatalogRepository{var refreshes=0;override fun observe(session:UserSession):Flow<List<CatalogProduct>> = flowOf(emptyList());override suspend fun refresh(session:UserSession):ProductResult{refreshes++;return ProductResult.Success("ok")};override suspend fun mutate(session:UserSession,requestId:String,mutation:ProductMutation,draft:ProductDraft)=ProductResult.Success("ok")}
 companion object{const val SHOP="11111111-1111-4111-8111-111111111111";const val ACTOR="22222222-2222-4222-8222-222222222222";const val VENDOR="33333333-3333-4333-8333-333333333333";const val BILL_ID="44444444-4444-4444-8444-444444444444";const val LINE="55555555-5555-4555-8555-555555555555";const val EVENT="66666666-6666-4666-8666-666666666666";const val REQUEST="77777777-7777-4777-8777-777777777777";val OWNER=UserSession(ACTOR,"Owner",UserRole.OWNER,SHOP);val BILL=VendorBill(BILL_ID,VENDOR,"received","INV-1","2026-07-29","2026-07-29T00:00:00Z",10000,10000,listOf(VendorReceiptLine(LINE,"88888888-8888-4888-8888-888888888888","Bag","B-1",2,5000,0,2)));val LEDGER=VendorLedger(listOf(BILL));val PAYMENT=VendorPaymentDraft(VENDOR,VendorPaymentMethod.CASH,"2026-07-29",listOf(VendorPaymentAllocationDraft(BILL_ID,5000)));val RETURN=VendorReturnDraft(BILL_ID,"2026-07-29","damaged",listOf(VendorReturnLineDraft(LINE,1)));val POSTED_PAYMENT=PostedVendorPayment(EVENT,VENDOR,5000,1,5000);val POSTED_RETURN=PostedVendorReturn(EVENT,BILL_ID,5000,5000,1)}
}
